using System;using System.Linq;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Threading;using TrayLeaf;using System.IO;
class Version100DialogTests{
 static int passed,failed;static Application app;static Window w;static Controller c;static string work;static object Call(string name,params object[] args){return typeof(Controller).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,args);}static void Check(bool ok,string name){Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(ok)passed++;else failed++;}
 static System.Collections.Generic.IEnumerable<T> Find<T>(DependencyObject root)where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var n=VisualTreeHelper.GetChild(root,i);if(n is T)yield return(T)n;foreach(var x in Find<T>(n))yield return x;}}
 static DispatcherTimer Drive(Action<Window> action){var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(120)};int ticks=0;timer.Tick+=delegate{if(++ticks>40){timer.Stop();foreach(var d in app.Windows.OfType<Window>().Where(x=>x!=w).ToArray())d.Close();throw new Exception("Dialog driver timed out");}var dialog=app.Windows.OfType<Window>().LastOrDefault(x=>x!=w&&x.IsVisible);if(dialog!=null)dialog.Dispatcher.BeginInvoke(new Action(()=>{if(dialog.IsVisible)action(dialog);}));};timer.Start();return timer;}
 static void Click(Button b){b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
 [STAThread]static int Main(string[] args){try{work=args[0];Directory.CreateDirectory(work);app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};using(var s=typeof(Entry).Assembly.GetManifestResourceStream("TrayLeaf.MainWindow.xaml"))w=(Window)System.Windows.Markup.XamlReader.Load(s);w.ShowActivated=false;w.Left=-10000;w.Top=-10000;using(var db=new Database(Path.Combine(work,"flow-"+Guid.NewGuid()+".db"))){c=new Controller(app,w,db,true);c.Start(null);var source=new AppRow{Name="Source",Path=@"C:\Apps\Source.exe",ProcessName="Source.exe"};var target=new AppRow{Name="Target",Path=@"C:\Apps\Target.exe",ProcessName="Target.exe",Args="--original"};var timer=Drive(d=>{var confirm=Find<Button>(d).FirstOrDefault(b=>Convert.ToString(b.Content)=="确认关联");if(confirm==null)return;Find<TextBox>(d).Single().Text="--edited";Check(Find<Image>(d).Any(i=>i.Width==88&&i.Source!=null),"generated-transparent-icon-loaded");Check(Find<Button>(d).Any(b=>b.Name=="DialogCloseButton"),"relation-editor-has-close-x");Click(confirm);});bool result=(bool)Call("EditAssociation",w,source,target);timer.Stop();Check(result&&db.Associations().Single().Target.Args=="--edited","confirmation-persists-edited-args");
 timer=Drive(d=>{var close=Find<Button>(d).First(b=>b.Name=="DialogCloseButton");Click(close);});result=(bool)Call("EditAssociation",w,source,new AppRow{Name="Cancelled",Path=@"C:\Apps\Cancelled.exe"});timer.Stop();Check(!result&&db.Associations().Single().Target.Path==target.Path,"close-x-cancels-without-write");
 c.launchFilePicker=owner=>new AppRow{Name="Chosen",Path=@"C:\Apps\Chosen.exe",ProcessName="Chosen.exe",Args="--picked"};timer=Drive(d=>{var choose=Find<Button>(d).FirstOrDefault(b=>Convert.ToString(b.Content)=="选择关联启动的程序");if(choose!=null){Click(choose);return;}var confirm=Find<Button>(d).FirstOrDefault(b=>Convert.ToString(b.Content)=="确认关联");if(confirm!=null)Click(confirm);});result=(bool)Call("ChooseAssociationTarget",w,source);timer.Stop();Check(result&&db.Associations().Single().Target.Path==@"C:\Apps\Chosen.exe","choose-confirm-closes-dialog-chain");Check(!app.Windows.OfType<Window>().Any(d=>d!=w&&d.IsVisible),"no-child-window-left-open");
 c.launchFilePicker=owner=>new AppRow{Name="Reselected",Path=@"C:\Apps\New.exe",Args=""};bool reselected=false;timer=Drive(d=>{if(!reselected){reselected=true;Click(Find<Button>(d).First(b=>Convert.ToString(b.Content)=="重新选择"));}else Click(Find<Button>(d).First(b=>Convert.ToString(b.Content)=="确认关联"));});result=(bool)Call("EditAssociation",w,source,target);timer.Stop();Check(result&&db.Associations().Single().Target.Path==@"C:\Apps\New.exe","reselect-replaces-target");
 Call("Exit");}app.Shutdown();Console.WriteLine("RESULT passed="+passed+" failed="+failed);return failed==0?0:1;}catch(Exception ex){Console.Error.WriteLine(ex);return 2;}}

}
